+    pub entity_urn: String,
+    pub title: String,
+    pub role: SessionHandoffUpwardContextRole,
+}
+
+/// A ticket included in a handoff together with its local implementation context.
+#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
