+    #[serde(default, skip_serializing_if = "Vec::is_empty")]
+    pub acceptance_criteria: Vec<String>,
+}
+
+#[derive(Deserialize)]
+#[serde(untagged)]
+enum SessionHandoffTargetTicketRepr {
+    Legacy(String),
+    Structured {
+        id: String,
+        #[serde(default)]
+        why: String,
+        #[serde(default)]
+        state: String,
+        #[serde(default)]
+        acceptance_criteria: Vec<String>,
+    },
+}
+
