+        match SessionHandoffTargetTicketRepr::deserialize(deserializer)? {
+            SessionHandoffTargetTicketRepr::Legacy(id) => Ok(Self {
+                id,
+                why: String::new(),
+                state: String::new(),
+                acceptance_criteria: Vec::new(),
+            }),
+            SessionHandoffTargetTicketRepr::Structured {
+                id,
+                why,
+                state,
+                acceptance_criteria,
+            } => Ok(Self {
+                id,
+                why,
+                state,
+                acceptance_criteria,
+            }),
+        }
+    }
+}
